messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
        {
            "imports": {
                "three": "./three.module.js"
            }
        }
    </script>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(-6, 4, 6); // Side-on camera
        camera.lookAt(0, 2, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Treadmill Ground ---
        const groundGeo = new THREE.PlaneGeometry(20, 10);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Humanoid Construction ---
        const humanoid = new THREE.Group();
        const material = new THREE.MeshStandardMaterial({ color: 0xff6347 }); // Tomato red
        const jointMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });

        // Helper to create limbs
        function createLimb(width, height, depth, yOffset) {
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mesh = new THREE.Mesh(geo, material);
            mesh.position.y = yOffset;
            mesh.castShadow = true;
            return mesh;
        }

        // Torso
        const torso = createLimb(1, 1.5, 0.6, 1.75);
        humanoid.add(torso);

        // Head
        const headGeo = new THREE.BoxGeometry(0.6, 0.6, 0.6);
        const head = new THREE.Mesh(headGeo, material);
        head.position.y = 2.8;
        head.castShadow = true;
        humanoid.add(head);

        // Arms
        const armGeo = new THREE.BoxGeometry(0.25, 1.2, 0.25);

        const leftArmPivot = new THREE.Group();
        leftArmPivot.position.set(-0.6, 2.2, 0);
        const leftArm = new THREE.Mesh(armGeo, material);
        leftArm.position.y = -0.6;
        leftArm.castShadow = true;
        leftArmPivot.add(leftArm);
        humanoid.add(leftArmPivot);

        const rightArmPivot = new THREE.Group();
        rightArmPivot.position.set(0.6, 2.2, 0);
        const rightArm = new THREE.Mesh(armGeo, material);
        rightArm.position.y = -0.6;
        rightArm.castShadow = true;
        rightArmPivot.add(rightArm);
        humanoid.add(rightArmPivot);

        // Legs
        const legGeo = new THREE.BoxGeometry(0.3, 1.2, 0.3);

        const leftLegPivot = new THREE.Group();
        leftLegPivot.position.set(-0.3, 1.1, 0);
        const leftLeg = new THREE.Mesh(legGeo, material);
        leftLeg.position.y = -0.6;
        leftLeg.castShadow = true;
        leftLegPivot.add(leftLeg);
        humanoid.add(leftLegPivot);

        const rightLegPivot = new THREE.Group();
        rightLegPivot.position.set(0.3, 1.1, 0);
        const rightLeg = new THREE.Mesh(legGeo, material);
        rightLeg.position.y = -0.6;
        rightLeg.castShadow = true;
        rightLegPivot.add(rightLeg);
        humanoid.add(rightLegPivot);

        scene.add(humanoid);

        // --- Animation Logic ---
        const CYCLE_DURATION = 10; // 2s stand + 3s walk + 3s run + 2s stand
        const TOLERANCE = 0.05;

        function animate() {
            requestAnimationFrame(animate);

            const time = (performance.now() / 1000) % CYCLE_DURATION;

            // Determine Phase
            let phase = 'stand';
            let localTime = 0;
            let speedMultiplier = 1;

            if (time < 2) {
                phase = 'stand';
                localTime = time;
            } else if (time < 5) {
                phase = 'walk';
                localTime = time - 2;
                speedMultiplier = 1; // Walking speed
            } else if (time < 8) {
                phase = 'run';
                localTime = time - 5;
                speedMultiplier = 2.5; // Running speed
            } else {
                phase = 'stand';
                localTime = time - 8;
            }

            // Calculate Swing Angles
            // Sine wave for swinging. 
            // Walk: amplitude ~0.5 rad. Run: amplitude ~0.9 rad.
            const amplitude = phase === 'run' ? 0.9 : 0.5;

            // Offset phases for opposite limbs
            const walkCycle = localTime * speedMultiplier;
            const legAngle = Math.sin(walkCycle * Math.PI * 2) * amplitude;
            const armAngle = Math.cos(walkCycle * Math.PI * 2) * amplitude; // Arms move opposite to legs

            // Apply Limb Rotations
            // Left Leg: Forward/Back
            leftLegPivot.rotation.x = legAngle;
            // Right Leg: Back/Forth
            rightLegPivot.rotation.x = -legAngle;

            // Left Arm: Back/Forth (Opposite to Left Leg)
            leftArmPivot.rotation.x = -armAngle;
            // Right Arm: Forward/Back (Opposite to Right Leg)
            rightArmPivot.rotation.x = armAngle;

            // Apply Posture Changes
            // Lean forward during run
            const targetLean = phase === 'run' ? 0.15 : 0;
            // Smoothly interpolate lean
            humanoid.rotation.z = THREE.MathUtils.lerp(humanoid.rotation.z, targetLean, 0.1);

            // Slight bounce during run
            const bounce = phase === 'run' ? Math.sin(walkCycle * Math.PI * 4) * 0.05 : 0;
            humanoid.position.y = bounce;

            // Render
            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Animation
        animate();
    </script>
</body>
</html>
```
